import * as React from "react";
import { controlStyles, numberInputSettings } from "@/components/ui/kalos-styles";
import { cn } from "@/lib/utils";

export function KalosNumberInputValue({ prefix, unit, children }: { prefix?: React.ReactNode; unit?: string; children: React.ReactNode }) {
  return <div className={controlStyles.numberValue}>
    {prefix != null ? <span aria-hidden="true" className={controlStyles.numberAffix}>{prefix}</span> : null}
    {children}
    {unit ? <span aria-hidden="true" className={cn(controlStyles.numberAffix, "ml-1.5")}>{unit}</span> : null}
  </div>;
}

export function useNumberInputMotion(inputRef: React.RefObject<HTMLInputElement | null>, value: number | null) {
  const previous = React.useRef(value);
  React.useEffect(() => {
    const old = previous.current;
    previous.current = value;
    const input = inputRef.current;
    if (!input || old === value || old === null || value === null || document.activeElement === input) return;
    const animation = input.animate([
      { transform: `translateY(${value > old ? 3 : -3}px)`, opacity: 0.45 },
      { transform: "translateY(0)", opacity: 1 },
    ], { duration: numberInputSettings.duration, easing: "cubic-bezier(0.22, 1, 0.36, 1)" });
    return () => animation.cancel();
  }, [inputRef, value]);
}

export function useNumberInputReset(inputRef: React.RefObject<HTMLInputElement | null>, reset: () => void) {
  const onReset = React.useEffectEvent(reset);
  React.useEffect(() => {
    const form = inputRef.current?.form;
    if (!form) return;
    const handleReset = (event: Event) => queueMicrotask(() => { if (!event.defaultPrevented) onReset(); });
    form.addEventListener("reset", handleReset);
    return () => form.removeEventListener("reset", handleReset);
  }, [inputRef]);
}

import type { ComponentProps, ReactNode } from "react";

export type KalosNumberInputProps = Omit<ComponentProps<"input">, "value" | "defaultValue" | "onChange" | "type" | "size" | "min" | "max" | "step" | "prefix"> & {
  label: string;
  value?: number | null;
  defaultValue?: number | null;
  onValueChange?: (value: number | null) => void;
  min?: number;
  max?: number;
  step?: number;
  largeStep?: number;
  prefix?: ReactNode;
  unit?: string;
  locale?: string;
  formatOptions?: Intl.NumberFormatOptions;
  hint?: string;
  error?: string;
  inputClassName?: string;
};

export function clampNumber(value: number | null, min = -Infinity, max = Infinity) {
  return value === null || !Number.isFinite(value) ? null : Math.min(Math.max(value, min), max);
}

export function stepNumber(value: number | null, direction: number, step = 1, min = -Infinity, max = Infinity, amount = step) {
  const safeStep = Number.isFinite(step) && step > 0 ? step : 1;
  const origin = Number.isFinite(min) ? min : 0;
  const start = value ?? (Number.isFinite(min) ? min : Number.isFinite(max) && max < 0 ? max : 0);
  if (value === null) return clampNumber(start, min, max);
  const position = (start - origin) / safeStep;
  const rounded = Math.round(position);
  const aligned = Math.abs(position - rounded) < 1e-8;
  const next = aligned
    ? start + direction * amount
    : origin + (direction > 0 ? Math.ceil(position) : Math.floor(position)) * safeStep;
  return clampNumber(Number(next.toPrecision(15)), min, max);
}

export function createNumberFormatter(locale = "zh-CN", options: Intl.NumberFormatOptions = {}) {
  const formatter = new Intl.NumberFormat(locale, { maximumFractionDigits: 20, ...options });
  const parts = formatter.formatToParts(-12345.6);
  const decimal = new Intl.NumberFormat(locale).formatToParts(1.1).find(part => part.type === "decimal")?.value ?? ".";
  const groups = new Set(parts.filter(part => part.type === "group").map(part => part.value));
  const symbols = parts.filter(part => ["currency", "percentSign", "unit", "literal"].includes(part.type)).map(part => part.value);
  const digits = Array.from({ length: 10 }, (_, digit) => new Intl.NumberFormat(locale, { useGrouping: false }).format(digit));
  return {
    format: (value: number | null) => value === null ? "" : formatter.format(value),
    parse(text: string): number | null {
      let normalized = text.trim();
      if (!normalized) return null;
      digits.forEach((digit, value) => { normalized = normalized.replaceAll(digit, String(value)); });
      for (const group of groups) normalized = normalized.replaceAll(group, "");
      for (const symbol of symbols) normalized = normalized.replaceAll(symbol, "");
      normalized = normalized.replaceAll(decimal, ".").replace(/[−﹣－]/g, "-").replace(/[\s\u200e\u200f\u061c]/g, "");
      if (!/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)$/.test(normalized)) return NaN;
      const value = Number(normalized) / (options.style === "percent" ? 100 : 1);
      return Number.isFinite(value) ? value : NaN;
    },
  };
}

"use client";
import { useRef, useState, type Ref } from "react";
import { CalendarDays, ChevronDown } from "lucide-react";
import { Popover } from "@base-ui/react/popover";
import { cn } from "cn";
import { KalosCalendar } from "@/components/ui/kalos-calendar";
import { clampDay, dateFormatter, dateKey, localDay, monthStart, validDate } from "@/components/ui/kalos-date-model";
import { KalosPickerField, usePickerIds, type KalosPickerFieldProps } from "@/components/ui/kalos-picker-field";
import { useSelectFocus } from "@/components/ui/kalos-select-focus";
import { controlStyles } from "@/components/ui/kalos-styles";
import { pickerCss } from "@/components/ui/kalos-picker-styles";

export type KalosDatePickerProps = KalosPickerFieldProps & {
  value?: Date | null; defaultValue?: Date | null; onChange?: (date: Date) => void;
  min?: Date; max?: Date; isDateDisabled?: (date: Date) => boolean; locale?: string; weekStartsOn?: 0 | 1;
  placeholder?: string; name?: string; today?: Date; open?: boolean; defaultOpen?: boolean; onOpenChange?: (open: boolean) => void; ref?: Ref<HTMLButtonElement>;
};
export function KalosDatePicker({ value, defaultValue = null, onChange, min, max, isDateDisabled, locale = "zh-CN", weekStartsOn = 1, placeholder = "选择日期", name, today: todayProp, open: controlledOpen, defaultOpen = false, onOpenChange, ref, ...field }: KalosDatePickerProps) {
  const today = localDay(validDate(todayProp) ? todayProp : new Date());
  const minimum = validDate(min) ? localDay(min) : undefined;
  const maximum = validDate(max) && (!minimum || max >= minimum) ? localDay(max) : undefined;
  const [own, setOwn] = useState(defaultValue);
  const selected = value === undefined ? own : value;
  const current = validDate(selected) ? localDay(selected) : null;
  const [ownOpen, setOwnOpen] = useState(defaultOpen);
  const open = !field.disabled && (controlledOpen ?? ownOpen);
  const [month, setMonth] = useState(() => monthStart(clampDay(current ?? today, minimum, maximum)));
  const ids = usePickerIds(field.id), valueId = `${ids.id}-value`;
  const control = useRef<HTMLDivElement>(null), keyboard = useRef(false);
  const { focused, popupRef, onOpenChange: focusOpenChange, finalFocus } = useSelectFocus(control, field.disabled);
  function changeOpen(next: boolean) {
    if (next && field.disabled) return;
    if (controlledOpen === undefined) setOwnOpen(next);
    if (next) setMonth(monthStart(clampDay(current ?? today, minimum, maximum)));
    focusOpenChange(next); onOpenChange?.(next);
  }
  return <KalosPickerField {...field} {...ids}>
    <style href="kalos-picker" precedence="default">{pickerCss}</style>
    <Popover.Root open={open} onOpenChange={changeOpen}>
      <div ref={control} className={cn(controlStyles.selectControl, "kalos-picker-control")} data-focus-managed data-focused={focused || undefined} data-invalid={!!field.error} data-disabled={field.disabled || undefined}>
        <Popover.Trigger id={ids.id} ref={ref} disabled={field.disabled} className={cn(controlStyles.selectTrigger, "kalos-picker-trigger")} aria-label={field.label == null ? field["aria-label"] ?? "选择日期" : undefined} aria-labelledby={field.label != null ? `${ids.labelId} ${valueId}` : undefined} aria-describedby={field.error || field.hint ? ids.messageId : undefined} aria-invalid={!!field.error} aria-required={field.required || undefined} onKeyDown={event => {
          if (["Enter", " ", "ArrowDown"].includes(event.key)) keyboard.current = true;
          if (event.key === "ArrowDown") { event.preventDefault(); changeOpen(true); }
        }}>
          <CalendarDays strokeWidth={1.5} aria-hidden="true" />
          <span id={valueId} key={current ? dateKey(current) : "empty"} className="kalos-picker-value" data-empty={!current || undefined}>{current ? dateFormatter(locale, { year: "numeric", month: "short", day: "numeric", weekday: "short" }).format(current) : placeholder}</span>
          <ChevronDown strokeWidth={1.5} aria-hidden="true" className="kalos-picker-chevron" />
        </Popover.Trigger>
      </div>
      <Popover.Portal><Popover.Positioner sideOffset={6} align="start" collisionPadding={8} className="kalos-picker-positioner">
        <Popover.Popup ref={node => { popupRef.current = node; }} className="kalos-picker-popup kalos-date-popup" aria-label="选择日期" initialFocus={() => { const target = keyboard.current ? popupRef.current?.querySelector<HTMLElement>('[data-date][tabindex="0"]') : false; keyboard.current = false; return target || (!defaultOpen ? popupRef.current : false); }} finalFocus={finalFocus}>
          <KalosCalendar month={month} onMonthChange={setMonth} value={current} today={today} min={minimum} max={maximum} isDateDisabled={isDateDisabled} locale={locale} weekStartsOn={weekStartsOn} onSelect={date => { if (value === undefined) setOwn(date); onChange?.(date); changeOpen(false); }} />
        </Popover.Popup>
      </Popover.Positioner></Popover.Portal>
    </Popover.Root>
    {name ? <input type="hidden" name={name} value={current ? dateKey(current) : ""} disabled={field.disabled} /> : null}
  </KalosPickerField>;
}

"use client";
import { useLayoutEffect, useRef, useState, type KeyboardEvent } from "react";
import { ChevronLeft, ChevronRight } from "lucide-react";
import { addDays, addMonths, calendarDays, clampDay, dateFormatter, dateKey, localDay, monthStart, sameDay, sameMonth, type KalosDateRange } from "./kalos-date-model";

export type KalosCalendarProps = {
  month: Date; onMonthChange: (date: Date) => void; value?: Date | null; range?: KalosDateRange | null;
  preview?: KalosDateRange | null; today: Date; min?: Date; max?: Date; isDateDisabled?: (date: Date) => boolean; locale?: string; weekStartsOn?: 0 | 1;
  months?: 1 | 2; disabled?: boolean; onSelect: (date: Date) => void; onHover?: (date: Date | null) => void;
};
export function KalosCalendar({ month, onMonthChange, value, range, preview, today, min, max, isDateDisabled, locale = "zh-CN", weekStartsOn = 1, months = 1, disabled: inactive = false, onSelect, onHover }: KalosCalendarProps) {
  const [focused, setFocused] = useState(() => clampDay(value ?? range?.end ?? today, min, max));
  const root = useRef<HTMLDivElement>(null);
  const pendingFocus = useRef<string | null>(null);
  const [motion, setMotion] = useState({ month: month.getTime(), direction: 1 });
  if (motion.month !== month.getTime()) setMotion({ month: month.getTime(), direction: month.getTime() < motion.month ? -1 : 1 });
  const direction = motion.direction;
  const accessibleDate = dateFormatter(locale, { year: "numeric", month: "long", day: "numeric", weekday: "long" });
  useLayoutEffect(() => { if (pendingFocus.current) { root.current?.querySelector<HTMLButtonElement>(`[data-date="${pendingFocus.current}"]`)?.focus(); pendingFocus.current = null; } }, [month, focused]);
  const endMonth = addMonths(monthStart(month), months);
  const visibleFocus = focused >= monthStart(month) && focused < endMonth ? focused : monthStart(month);
  const disabled = (date: Date) => !!(inactive || min && date < localDay(min) || max && date > localDay(max) || isDateDisabled?.(date));
  const within = (date: Date, selected?: KalosDateRange | null) => !!selected && date >= selected.start && date <= selected.end;
  const navigate = (offset: number) => { const next = addMonths(monthStart(month), offset); onMonthChange(next); setFocused(addMonths(visibleFocus, offset)); };
  function keyboard(event: KeyboardEvent<HTMLButtonElement>, date: Date) {
    if (inactive) return;
    let next: Date;
    const start = (date.getDay() - weekStartsOn + 7) % 7;
    const rtl = getComputedStyle(event.currentTarget).direction === "rtl";
    switch (event.key) {
      case "ArrowLeft": next = addDays(date, rtl ? 1 : -1); break;
      case "ArrowRight": next = addDays(date, rtl ? -1 : 1); break;
      case "ArrowUp": next = addDays(date, -7); break;
      case "ArrowDown": next = addDays(date, 7); break;
      case "Home": next = addDays(date, -start); break;
      case "End": next = addDays(date, 6 - start); break;
      case "PageUp": next = addMonths(date, event.shiftKey ? -12 : -1); break;
      case "PageDown": next = addMonths(date, event.shiftKey ? 12 : 1); break;
      default: return;
    }
    event.preventDefault(); next = localDay(next); pendingFocus.current = dateKey(next); setFocused(next);
    if (next < monthStart(month)) onMonthChange(monthStart(next)); else if (next >= endMonth) onMonthChange(addMonths(monthStart(next), 1 - months));
    onHover?.(disabled(next) ? null : next);
  }
  return <div ref={root} className="kalos-calendar" data-months={months} onMouseLeave={() => onHover?.(null)}>
    <div className="kalos-calendar-nav">
      <button type="button" aria-label="上个月" disabled={inactive} onClick={() => navigate(-1)}><ChevronLeft aria-hidden="true" /></button>
      <button type="button" aria-label="下个月" disabled={inactive} onClick={() => navigate(1)}><ChevronRight aria-hidden="true" /></button>
    </div>
    {Array.from({ length: months }, (_, index) => {
      const shown = addMonths(monthStart(month), index), days = calendarDays(shown, weekStartsOn);
      const title = dateFormatter(locale, { year: "numeric", month: "long" }).format(shown);
      return <div key={dateKey(shown)} className="kalos-calendar-month" data-second={index === 1 || undefined} data-direction={direction}>
        <div className="kalos-calendar-title" aria-live="polite">{title}</div>
        <div role="grid" aria-label={title} className="kalos-calendar-grid">
          <div role="row" className="kalos-calendar-weekdays">{Array.from({ length: 7 }, (_, day) => <span key={day} role="columnheader" aria-label={`星期${["日", "一", "二", "三", "四", "五", "六"][(day + weekStartsOn) % 7]}`}>{["日", "一", "二", "三", "四", "五", "六"][(day + weekStartsOn) % 7]}</span>)}</div>
          {Array.from({ length: 6 }, (_, week) => <div key={week} role="row" className="kalos-calendar-week">{days.slice(week * 7, week * 7 + 7).map(date => {
            const outside = !sameMonth(date, shown), chosen = sameDay(value, date) || sameDay(range?.start, date) || sameDay(range?.end, date);
            const band = preview ?? range;
            return <span key={dateKey(date)} role="gridcell" aria-selected={sameDay(value, date) || within(date, range)} className="kalos-calendar-cell" data-row-start={!outside && (date.getDay() === weekStartsOn || date.getDate() === 1) || undefined} data-row-end={!outside && ((date.getDay() - weekStartsOn + 7) % 7 === 6 || !sameMonth(addDays(date, 1), shown)) || undefined} data-range={!outside && within(date, band) || undefined} data-preview={!!preview || undefined} data-start={sameDay(band?.start, date) || undefined} data-end={sameDay(band?.end, date) || undefined}>
              {months === 2 && outside ? null : <button type="button" data-date={dateKey(date)} data-outside={outside || undefined} data-selected={chosen || undefined} aria-current={sameDay(date, today) ? "date" : undefined} aria-disabled={disabled(date) || undefined} aria-label={accessibleDate.format(date)} tabIndex={!inactive && sameDay(visibleFocus, date) && (!outside || months === 1) ? 0 : -1} onFocus={() => setFocused(date)} onMouseEnter={() => onHover?.(disabled(date) ? null : date)} onKeyDown={event => keyboard(event, date)} onClick={() => { if (!disabled(date)) onSelect(localDay(date)); }}>{date.getDate()}</button>}
            </span>;
          })}</div>)}
        </div>
      </div>;
    })}
  </div>;
}

export type KalosDateRange = { start: Date; end: Date };
export const validDate = (value: unknown): value is Date => value instanceof Date && Number.isFinite(value.getTime());
export function localDay(value: Date) { const day = new Date(value); day.setHours(0, 0, 0, 0); return day; }
export function addDays(value: Date, amount: number) { const day = localDay(value); day.setDate(day.getDate() + amount); return day; }
export function monthStart(value: Date) { const day = localDay(value); day.setDate(1); return day; }
export function addMonths(value: Date, amount: number) {
  const day = monthStart(value); day.setMonth(day.getMonth() + amount);
  const last = new Date(day); last.setMonth(last.getMonth() + 1); last.setDate(0);
  day.setDate(Math.min(value.getDate(), last.getDate())); return day;
}
export function dateKey(value: Date) { return `${String(value.getFullYear()).padStart(4, "0")}-${String(value.getMonth() + 1).padStart(2, "0")}-${String(value.getDate()).padStart(2, "0")}`; }
export const sameDay = (a?: Date | null, b?: Date | null) => !!a && !!b && dateKey(a) === dateKey(b);
export const sameMonth = (a: Date, b: Date) => a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth();
export function dayCount(range: KalosDateRange) { return Math.round((Date.UTC(range.end.getFullYear(), range.end.getMonth(), range.end.getDate()) - Date.UTC(range.start.getFullYear(), range.start.getMonth(), range.start.getDate())) / 86400000) + 1; }
export function orderedRange(a: Date, b: Date): KalosDateRange { return a <= b ? { start: localDay(a), end: localDay(b) } : { start: localDay(b), end: localDay(a) }; }
export function calendarDays(month: Date, weekStartsOn = 1) { const first = monthStart(month); const start = addDays(first, -((first.getDay() - weekStartsOn + 7) % 7)); return Array.from({ length: 42 }, (_, index) => addDays(start, index)); }
export function dateFormatter(locale = "zh-CN", options: Intl.DateTimeFormatOptions = {}) {
  try { return new Intl.DateTimeFormat(locale, { calendar: "gregory", ...options }); }
  catch { return new Intl.DateTimeFormat("zh-CN", { calendar: "gregory", ...options }); }
}
export function formatRange(range: KalosDateRange, locale = "zh-CN") { const format = dateFormatter(locale, { year: "numeric", month: "short", day: "numeric" }); return `${format.format(range.start)} – ${format.format(range.end)}`; }
export function clampDay(value: Date, min?: Date, max?: Date) { return min && value < localDay(min) ? localDay(min) : max && value > localDay(max) ? localDay(max) : localDay(value); }
export const datePresets = [
  { id: "today", label: "今天", range: (today: Date) => ({ start: today, end: today }) },
  { id: "yesterday", label: "昨天", range: (today: Date) => ({ start: addDays(today, -1), end: addDays(today, -1) }) },
  ...[7, 30, 90].map(days => ({ id: `last-${days}`, label: `最近 ${days} 天`, range: (today: Date) => ({ start: addDays(today, 1 - days), end: today }) })),
  { id: "month", label: "本月", range: (today: Date) => ({ start: monthStart(today), end: today }) },
  { id: "last-month", label: "上月", range: (today: Date) => ({ start: addMonths(monthStart(today), -1), end: addDays(monthStart(today), -1) }) },
  { id: "quarter", label: "本季度", range: (today: Date) => ({ start: addMonths(monthStart(today), -(today.getMonth() % 3)), end: today }) },
  { id: "year", label: "今年至今", range: (today: Date) => { const start = monthStart(today); start.setMonth(0); return { start, end: today }; } },
];

