  action?: ReactNode;
  children?: ReactNode;
  footer?: ReactNode;
  interactive?: boolean;
  selected?: boolean;
};

export function KalosCard({
  as = "div",
  title,
  titleAs: Title = "h3",
  description,
  icon,
  action,
  children,
  footer,
  interactive = false,
  selected = false,
  className,
  ...props
}: KalosCardProps) {
  return createElement(
    as,
    {
      ...props,
      "data-slot": "card",
      "data-interactive": interactive || undefined,
      "data-selected": selected || undefined,
      className: [controlStyles.card, className].filter(Boolean).join(" "),
